import unittest
from bfs import shortest_path_len


class Regression(unittest.TestCase):
    def test_square(self):
        self.assertEqual(shortest_path_len(["...", "...", "..."], (0, 0), (2, 2)), 4)

    def test_wall_forces_detour(self):
        grid = ["...", ".#.", "..."]
        self.assertEqual(shortest_path_len(grid, (1, 0), (1, 2)), 4)

    def test_wide_grid_fully_blocked(self):
        grid = ["..#..", "..#.."]
        self.assertEqual(shortest_path_len(grid, (0, 0), (0, 4)), -1)

    def test_tall_grid(self):
        self.assertEqual(shortest_path_len([".", ".", ".", "."], (0, 0), (3, 0)), 3)

